# ─── HELPERS ───────────────────────────────────────────────────────────────────
def fetch_plants():
    try: return requests.get(f"{API_BASE}/plants", timeout=5).json()
    except: return []

def fetch_plant_data(plant_id, limit=300):
    try: return requests.get(f"{API_BASE}/public/{plant_id}?limit={limit}", timeout=10).json()
    except: return None

def aqi_badge(aqi):
    try: v = float(aqi)
    except: return '<span class="bnormal">NORMAL</span>'
    if v > 300: return '<span class="bsevere">SEVERE</span>'
    if v > 200: return '<span class="bhigh">HIGH</span>'
    if v > 100: return '<span class="bmoderate">MODERATE</span>'
    return '<span class="bnormal">NORMAL</span>'

def aqi_color(aqi):
    try: v = float(aqi)
    except: return '#00e676'
    if v > 300: return '#ff1744'
    if v > 200: return '#ff6d00'
    if v > 100: return '#ffd600'
    return '#00e676'

def feed_color(sev):
    s = str(sev).lower()
    if 'severe' in s: return '#ff1744'
    if 'high' in s: return '#ff6d00'
    if 'mod' in s: return '#ffd600'
    return '#00e676'

def plotly_theme():
    return dict(
        paper_bgcolor='rgba(0,0,0,0)', plot_bgcolor='rgba(11,20,16,0.8)',
        font=dict(color='#7aad8f', family='IBM Plex Mono', size=10),
        xaxis=dict(gridcolor='#1a3326', linecolor='#1a3326'),
        yaxis=dict(gridcolor='#1a3326', linecolor='#1a3326'),
        margin=dict(l=40, r=20, t=20, b=40),
        legend=dict(bgcolor='rgba(0,0,0,0)', font=dict(size=10))
    )

